-- PostgreSQL Import – generiert am 2026-06-06T18:55:49.060009
-- Behörden-Datenbank

-- === TABELLEN ANLEGEN ===

CREATE TABLE IF NOT EXISTS behoerden (
    id TEXT PRIMARY KEY,
    excel_id INTEGER,
    schema_version TEXT,
    name TEXT NOT NULL,
    kuerzel TEXT,
    typ TEXT,
    rechtsform TEXT,
    ebene TEXT DEFAULT 'Bund',
    sitz TEXT,
    bundesland TEXT,
    lat DOUBLE PRECISION,
    lon DOUBLE PRECISION,
    gruendungsjahr INTEGER,
    aufgeloest BOOLEAN DEFAULT FALSE,
    aufgeloest_jahr INTEGER,
    zustaendigkeit TEXT,
    website TEXT,
    rechtsgrundlage TEXT,
    haushalt_mio_eur DOUBLE PRECISION,
    haushalt_jahr INTEGER,
    beschaeftigte INTEGER,
    beschaeftigte_jahr INTEGER,
    ministerium_id TEXT,
    ressort TEXT,
    klassifikation TEXT,
    anmerkung TEXT,
    vollstaendigkeit_prozent DOUBLE PRECISION,
    verifikation_noetig BOOLEAN,
    zuletzt_verifiziert TEXT,
    quellen_json JSONB,
    recherche_datum TEXT,
    recherche_agent_version TEXT,
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS beziehungen (
    id SERIAL PRIMARY KEY,
    von_id TEXT REFERENCES behoerden(id),
    zu_id TEXT,
    typ TEXT,
    richtung TEXT,
    seit INTEGER,
    quelle TEXT
);

